def execute_command(command_name: str, arguments: dict[str, str], agent: Agent) -> Any:
    """Execute the command and return the result

    Args:
        command_name (str): The name of the command to execute
        arguments (dict): The arguments for the command
        agent (Agent): The agent that is executing the command

    Returns:
        str: The result of the command
    """
    try:
        if (command := agent.command_registry.get_command(command_name)):
            return command(**arguments, agent=agent)
        for command in agent.ai_config.prompt_generator.commands:
            if command_name == command.label.lower() or command_name == command.name.lower():
                return command.function(**arguments)
        raise RuntimeError(f"Cannot execute '{command_name}': unknown command. Do not try to use this command again.")
    except Exception as e:
        return f'Error: {str(e)}'

