def extract_command(assistant_reply_json: dict, assistant_reply: ChatModelResponse, config: Config) -> tuple[str, dict[str, str]]:
    """Parse the response and return the command name and arguments

    Args:
        assistant_reply_json (dict): The response object from the AI
        assistant_reply (ChatModelResponse): The model response from the AI
        config (Config): The config object

    Returns:
        tuple: The command name and arguments

    Raises:
        json.decoder.JSONDecodeError: If the response is not valid JSON

        Exception: If any other error occurs
    """
    if config.openai_functions:
        if assistant_reply.function_call is None:
            return ('Error:', {'message': "No 'function_call' in assistant reply"})
        assistant_reply_json['command'] = {'name': assistant_reply.function_call.name, 'args': json.loads(assistant_reply.function_call.arguments)}
    try:
        if 'command' not in assistant_reply_json:
            return ('Error:', {'message': "Missing 'command' object in JSON"})
        if not isinstance(assistant_reply_json, dict):
            return ('Error:', {'message': f'The previous message sent was not a dictionary {assistant_reply_json}'})
        command = assistant_reply_json['command']
        if not isinstance(command, dict):
            return ('Error:', {'message': "'command' object is not a dictionary"})
        if 'name' not in command:
            return ('Error:', {'message': "Missing 'name' field in 'command' object"})
        command_name = command['name']
        arguments = command.get('args', {})
        return (command_name, arguments)
    except json.decoder.JSONDecodeError:
        return ('Error:', {'message': 'Invalid JSON'})
    except Exception as e:
        return ('Error:', {'message': str(e)})

