def run_interaction_loop(agent: Agent) -> None:
    """Run the main interaction loop for the agent.

    Args:
        agent: The agent to run the interaction loop for.

    Returns:
        None
    """
    config = agent.config
    ai_config = agent.ai_config
    logger.debug(f'{ai_config.ai_name} System Prompt: {agent.system_prompt}')
    cycle_budget = cycles_remaining = _get_cycle_budget(config.continuous_mode, config.continuous_limit)
    spinner = Spinner('Thinking...', plain_output=config.plain_output)

    def graceful_agent_interrupt(signum: int, frame: Optional[FrameType]) -> None:
        nonlocal cycle_budget, cycles_remaining, spinner
        if cycles_remaining in [0, 1, math.inf]:
            logger.typewriter_log('Interrupt signal received. Stopping continuous command execution immediately.', Fore.RED)
            sys.exit()
        else:
            restart_spinner = spinner.running
            if spinner.running:
                spinner.stop()
            logger.typewriter_log('Interrupt signal received. Stopping continuous command execution.', Fore.RED)
            cycles_remaining = 1
            if restart_spinner:
                spinner.start()
    signal.signal(signal.SIGINT, graceful_agent_interrupt)
    while cycles_remaining > 0:
        logger.debug(f'Cycle budget: {cycle_budget}; remaining: {cycles_remaining}')
        with spinner:
            (command_name, command_args, assistant_reply_dict) = agent.think()
        update_user(config, ai_config, command_name, command_args, assistant_reply_dict)
        if cycles_remaining == 1:
            (user_feedback, user_input, new_cycles_remaining) = get_user_feedback(config, ai_config)
            if user_feedback == UserFeedback.AUTHORIZE:
                if new_cycles_remaining is not None:
                    if cycle_budget > 1:
                        cycle_budget = new_cycles_remaining + 1
                    cycles_remaining = new_cycles_remaining + 1
                else:
                    if cycle_budget > 1:
                        logger.typewriter_log('RESUMING CONTINUOUS EXECUTION: ', Fore.MAGENTA, f'The cycle budget is {cycle_budget}.')
                    cycles_remaining = cycle_budget + 1
                logger.typewriter_log('-=-=-=-=-=-=-= COMMAND AUTHORISED BY USER -=-=-=-=-=-=-=', Fore.MAGENTA, '')
            elif user_feedback == UserFeedback.EXIT:
                logger.typewriter_log('Exiting...', Fore.YELLOW)
                exit()
            else:
                command_name = 'human_feedback'
        else:
            user_input = None
            logger.typewriter_log('\n')
            if cycles_remaining != math.inf:
                logger.typewriter_log('AUTHORISED COMMANDS LEFT: ', Fore.CYAN, f'{cycles_remaining}')
        if command_name != 'human_feedback':
            cycles_remaining -= 1
        result = agent.execute(command_name, command_args, user_input)
        if result is not None:
            logger.typewriter_log('SYSTEM: ', Fore.YELLOW, result)
        else:
            logger.typewriter_log('SYSTEM: ', Fore.YELLOW, 'Unable to execute command')

