def generate_aiconfig_manual(config: Config, ai_config_template: Optional[AIConfig]=None) -> AIConfig:
    """
    Interactively create an AI configuration by prompting the user to provide the name, role, and goals of the AI.

    This function guides the user through a series of prompts to collect the necessary information to create
    an AIConfig object. The user will be asked to provide a name and role for the AI, as well as up to five
    goals. If the user does not provide a value for any of the fields, default values will be used.

    Params:
        config (Config): The Config object
        ai_config_template (AIConfig): The AIConfig object to use as a template

    Returns:
        AIConfig: An AIConfig object containing the user-defined or default AI name, role, and goals.
    """
    logger.typewriter_log('Create an AI-Assistant:', Fore.GREEN, 'Enter the name of your AI and its role below. Entering nothing will load defaults.', speak_text=True)
    if ai_config_template and ai_config_template.ai_name:
        ai_name = ai_config_template.ai_name
    else:
        ai_name = ''
        logger.typewriter_log('Name your AI: ', Fore.GREEN, "For example, 'Entrepreneur-GPT'")
        ai_name = utils.clean_input(config, 'AI Name: ')
    if ai_name == '':
        ai_name = 'Entrepreneur-GPT'
    logger.typewriter_log(f'{ai_name} here!', Fore.LIGHTBLUE_EX, 'I am at your service.', speak_text=True)
    if ai_config_template and ai_config_template.ai_role:
        ai_role = ai_config_template.ai_role
    else:
        logger.typewriter_log("Describe your AI's role: ", Fore.GREEN, "For example, 'an AI designed to autonomously develop and run businesses with the sole goal of increasing your net worth.'")
        ai_role = utils.clean_input(config, f'{ai_name} is: ')
    if ai_role == '':
        ai_role = 'an AI designed to autonomously develop and run businesses with the'
        ' sole goal of increasing your net worth.'
    if ai_config_template and ai_config_template.ai_goals:
        ai_goals = ai_config_template.ai_goals
    else:
        logger.typewriter_log('Enter up to 5 goals for your AI: ', Fore.GREEN, "For example: \nIncrease net worth, Grow Twitter Account, Develop and manage multiple businesses autonomously'")
        logger.info('Enter nothing to load defaults, enter nothing when finished.')
        ai_goals = []
        for i in range(5):
            ai_goal = utils.clean_input(config, f'{Fore.LIGHTBLUE_EX}Goal{Style.RESET_ALL} {i + 1}: ')
            if ai_goal == '':
                break
            ai_goals.append(ai_goal)
    if not ai_goals:
        ai_goals = ['Increase net worth', 'Grow Twitter Account', 'Develop and manage multiple businesses autonomously']
    logger.typewriter_log('Enter your budget for API calls: ', Fore.GREEN, 'For example: $1.50')
    logger.info('Enter nothing to let the AI run without monetary limit')
    api_budget_input = utils.clean_input(config, f'{Fore.LIGHTBLUE_EX}Budget{Style.RESET_ALL}: $')
    if api_budget_input == '':
        api_budget = 0.0
    else:
        try:
            api_budget = float(api_budget_input.replace('$', ''))
        except ValueError:
            logger.typewriter_log('Invalid budget input. Setting budget to unlimited.', Fore.RED)
            api_budget = 0.0
    return AIConfig(ai_name, ai_role, ai_goals, api_budget)

