def prompt_user(config: Config, ai_config_template: Optional[AIConfig]=None) -> AIConfig:
    """Prompt the user for input

    Params:
        config (Config): The Config object
        ai_config_template (AIConfig): The AIConfig object to use as a template

    Returns:
        AIConfig: The AIConfig object tailored to the user's input
    """
    logger.typewriter_log('Welcome to Auto-GPT! ', Fore.GREEN, "run with '--help' for more information.", speak_text=True)
    ai_config_template_provided = ai_config_template is not None and any([ai_config_template.ai_goals, ai_config_template.ai_name, ai_config_template.ai_role])
    user_desire = ''
    if not ai_config_template_provided:
        logger.typewriter_log('Create an AI-Assistant:', Fore.GREEN, "input '--manual' to enter manual mode.", speak_text=True)
        user_desire = utils.clean_input(config, f'{Fore.LIGHTBLUE_EX}I want Auto-GPT to{Style.RESET_ALL}: ')
    if user_desire.strip() == '':
        user_desire = DEFAULT_USER_DESIRE_PROMPT
    if '--manual' in user_desire or ai_config_template_provided:
        logger.typewriter_log('Manual Mode Selected', Fore.GREEN, speak_text=True)
        return generate_aiconfig_manual(config, ai_config_template)
    else:
        try:
            return generate_aiconfig_automatic(user_desire, config)
        except Exception as e:
            logger.typewriter_log('Unable to automatically generate AI Config based on user desire.', Fore.RED, 'Falling back to manual mode.', speak_text=True)
            logger.debug(f'Error during AIConfig generation: {e}')
            return generate_aiconfig_manual(config)

